<script>
(function(){
"use strict";

/* ---------- 공통 데이터: 설계 단계 ---------- */
// 각 단계는 "외곽 다각형 꼭짓점 수 + 모서리 절삭 비율 + 테이퍼 비율"을 개념적으로 정의
const STAGES = [
  { id:0, name:"1단계: 단순 매스", desc:"가장 단순한 사각 매스. 전체 높이 555m를 하나의 블록으로 가정한 초기 스터디.", sides:4, chamfer:0.0, taperTop:0.75, twist:0 },
  { id:1, name:"2단계: 모서리 절삭", desc:"사각 평면의 네 모서리를 깎아 팔각형에 가까운 형태로 변형. 도자기 곡선을 참고한 초기 접근.", sides:8, chamfer:0.25, taperTop:0.55, twist:0.05 },
  { id:2, name:"3단계: 테이퍼 강화", desc:"상부로 갈수록 평면을 더 작게 수렴시켜 뾰족한 실루엣을 강조.", sides:12, chamfer:0.3, taperTop:0.33, twist:0.12 },
  { id:3, name:"4단계: 곡면 다각형 근사", desc:"다각형 변의 수를 늘려 부드러운 곡선 외곽에 가깝게 근사, 최종 실루엣의 기초.", sides:20, chamfer:0.32, taperTop:0.22, twist:0.18 },
  { id:4, name:"5단계: 완성형 근사", desc:"완성 모델과 동일한 비율로 수렴한 최종 매스 스터디.", sides:28, chamfer:0.34, taperTop:0.165, twist:0.22 }
];

const TOTAL_HEIGHT = 555; // m, 공개 수치
const FLOORS = 123; // 공개 수치
const BASE_HALF = 32; // m, 저층부 반경 추정값 (변 ≈ 60m 추정 기반 역산)

/* ---------- 다각형 생성 유틸 (테이퍼 + 모서리 절삭 근사) ---------- */
function makePolygon(sides, chamfer, radius){
  // chamfer를 이용해 사각형->다각형으로 느껴지는 형태를 만듦 (완전 수학적 정밀성보다 시각적 근사 우선)
  const pts = [];
  const n = Math.max(sides,4);
  for(let i=0;i<n;i++){
    const a = (i/n) * Math.PI*2;
    // 사각 성향을 주기 위해 cos/sin 4차 superellipse 형태 혼합
    const squareness = 1-chamfer;
    const sx = Math.sign(Math.cos(a)) * Math.pow(Math.abs(Math.cos(a)), 2-squareness*1.3);
    const sy = Math.sign(Math.sin(a)) * Math.pow(Math.abs(Math.sin(a)), 2-squareness*1.3);
    pts.push(new THREE.Vector2(sx*radius, sy*radius));
  }
  return pts;
}

function buildTaperedMassGeometry(stage, totalHeightUnits){
  const segments = 10;
  const group = new THREE.Group();
  const colorLow = new THREE.Color(0x3a6ea5);
  const colorHigh = new THREE.Color(0xf0a84e);
  for(let s=0;s<segments;s++){
    const t0 = s/segments, t1=(s+1)/segments;
    const r0 = BASE_HALF * THREE.MathUtils.lerp(1, stage.taperTop, Math.pow(t0,1.15));
    const r1 = BASE_HALF * THREE.MathUtils.lerp(1, stage.taperTop, Math.pow(t1,1.15));
    const y0 = t0*totalHeightUnits, y1 = t1*totalHeightUnits;
    const twistAngle = stage.twist * t0 * Math.PI;
    const pts0 = makePolygon(stage.sides, stage.chamfer, r0);
    const pts1 = makePolygon(stage.sides, stage.chamfer, r1);

    const positions = [];
    const n = pts0.length;
    for(let i=0;i<n;i++){
      const j=(i+1)%n;
      const rot = twistAngle;
      const cosr=Math.cos(rot), sinr=Math.sin(rot);
      function rotp(p){ return new THREE.Vector2(p.x*cosr-p.y*sinr, p.x*sinr+p.y*cosr); }
      const a0=rotp(pts0[i]), b0=rotp(pts0[j]), a1=rotp(pts1[i]), b1=rotp(pts1[j]);
      // quad -> two triangles, side face
      positions.push(
        a0.x,y0,a0.y,  b0.x,y0,b0.y,  b1.x,y1,b1.y,
        a0.x,y0,a0.y,  b1.x,y1,b1.y,  a1.x,y1,a1.y
      );
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(positions,3));
